// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // First, make a deposit via receive to make depositsCount = 1
        vm.deal(address(this), 1 ether);
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success, "initial deposit failed");
        uint depositsBefore = c.depositsCount();

        // Now call sendMoney with the owner (default is this contract)
        vm.deal(address(c), 0 ether); // ensure no extra balance issues
        address payable target = payable(address(0x1234));
        c.sendMoney(target, 0);

        // After sendMoney, depositsCount should remain unchanged (no new deposit)
        assertTrue(c.depositsCount() == depositsBefore);
    }
}

