pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract so it can send money
        vm.deal(address(c), 1 ether);

        // First, make a deposit to increase depositsCount
        vm.deal(address(0x1), 1 wei);
        vm.prank(address(0x1));
        (bool success, ) = address(c).call{value: 1 wei}("");
        require(success, "deposit failed");

        // Now send money to another address – this does not change depositsCount
        vm.prank(c.owner());
        c.sendMoney(address(0x2), 1 wei);

        // After the call, depositsCount differs:
        // Reference increments on receive, so depositsCount = 1
        // Bug decrements on receive, so depositsCount = -1 (underflow) or 0? 
        // Actually with unchecked (not here) it would underflow; but depositCount is uint, so revert? 
        // The bug receive has require that passes? Let's check: depositsCount+1 >= depositsCount always true
        // Then depositsCount-- on uint when depositsCount=0 would revert in Solidity 0.8 (checked arithmetic).
        // So the buggy receive would revert on the first deposit, meaning depositsCount stays 0.
        // But we need the test to end with an assertion that passes on reference and fails on bug.
        // Alternative: do two deposits, then sendMoney, then compare depositsCount.
        // Let's reset: start fresh, do two deposits. Reference: depositsCount = 2; Bug: first deposit -> 0 (decrement from 0? Actually decrement from 0 to -1 reverts, so second deposit fails). 
        // So buggy contract would have depositsCount = 1 after first deposit (0+1=1, then decrement to 0? No: start 0, require true, depositsCount++ becomes 1 in reference; bug: require true, depositsCount-- becomes -1 -> revert). 
        // So buggy receive reverts on first deposit -> no change. To make them diverge, we need depositCount to be incremented in reference and decremented in bug without revert. 
        // But decrement on uint below 0 reverts; so bug contract never successfully increments depositsCount. 
        // Therefore a concrete witness: after one deposit (1 wei), reference.depositsCount = 1, bug.depositsCount = 0 (since receive reverts). 
        // Now call sendMoney (doesn't affect depositsCount). Then assert depositsCount == 1. 
        // On bug, depositsCount == 0, assertion fails.
    }
}

