import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(this);
        address target = address(0x1234);

        // send 1 wei to trigger receive(), which increments depositsCount in ref but decrements in bug
        vm.deal(owner, 1 wei);
        vm.deal(target, 0);
        vm.prank(owner);
        c.sendMoney{value: 1 wei}(target, 1 wei);

        // reference: depositsCount == 1; bug: depositsCount == 0
        assertTrue(c.depositsCount() == 1);
    }
}

