pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a target contract whose receive reverts
        RevertingTarget target = new RevertingTarget();
        vm.deal(address(c), 1 ether);
        vm.prank(c.owner());
        // This call will succeed on reference (call) and revert on bug (transfer)
        c.sendMoney(address(target), 1 wei);
        // After the call, reference has depositsCount = 1, bug stays at 0
        assertTrue(c.depositsCount() == 1);
    }
}

contract RevertingTarget {
    receive() external payable {
        revert("revert");
    }
}
